/**
 * Executes the configured Knight duel opportunity with captured actor and target bodies. Inputs
 * are the day context, provider and gateway; outputs are a validated duel selection and its
 * existing commit effects. It does not let a replaced or dead actor reuse the captured window.
 */
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import { COMPONENT } from "../../core/domain/components/names";
import { AliveComponent, aliveLifeVersion } from "../../core/domain/components/alive";
import type { RoleComponent } from "../../core/domain/components/role";
import {
  Role,
  Phase,
  KnightDuelWindow as DuelWindow,
  type ActionProvider,
  type KnightDuelSelection,
  type KnightDuelCommit,
} from "../../core/domain/model";
import type { World } from "../../core/domain/world";
import { ToolGateway } from "../gateway/tool_gateway";
import { GameActionRequestFactory } from "./action_request_factory";
import { getKnightState } from "../mechanisms/roles/knight/ports";

interface DuelParticipantSnapshot {
  life: AliveComponent;
  version: ReturnType<typeof aliveLifeVersion>;
  role: RoleComponent;
  roleId: Role;
  camp: RoleComponent["camp"];
}

/** A discrete living-player action; all final mutations belong to the supplied manager callback. */
export class KnightDuelWindow {
  constructor(
    private readonly world: World,
    private readonly gateway: ToolGateway,
  ) {}
  async execute(
    config: ReadonlyBoardConfig,
    requests: GameActionRequestFactory,
    provider: ActionProvider,
    window: DuelWindow,
    isCurrent: () => boolean,
    commit?: (choice: KnightDuelSelection) => Promise<KnightDuelCommit>,
  ): Promise<{ selection: KnightDuelSelection | null; endsDay: boolean }> {
    const empty = { selection: null, endsDay: false };
    if (
      !isCurrent() ||
      !(config.knight?.enabledWindows ?? [DuelWindow.AfterSpeeches]).includes(window)
    )
      return empty;
    if (
      !this.world.getAliveEntityIds().some((id) => {
        const role = this.world.getComponent(id, COMPONENT.Role);
        return role?.role === Role.Knight && getKnightState(role)?.canDuel === true;
      })
    )
      return empty;
    const snapshots = new Map<number, DuelParticipantSnapshot>(
      this.world.getAliveEntityIds().map((id) => {
        const life = this.world.getComponent(id, COMPONENT.Alive)!,
          role = this.world.getComponent(id, COMPONENT.Role)!;
        return [
          id,
          { life, version: aliveLifeVersion(life), role, roleId: role?.role, camp: role?.camp },
        ] as const;
      }),
    );
    const picks = await Promise.all(
      [...snapshots].map(async ([actorId, actor]) => {
        const state = actor.role?.role === Role.Knight ? getKnightState(actor.role) : undefined;
        if (state?.canDuel !== true) return null;
        const action = await provider.getAction(
          requests.create({
            phase: Phase.Day,
            actorId,
            allowedTools: ["duel"],
            stage: window,
            requiresAction: false,
            summary: { key: "request.summary.knight_duel" },
            context: { duel_window: window },
          }),
        );
        if (action?.name !== "duel") return null;
        return { actorId, actor, state, action, target: snapshots.get(action.args.target_id) };
      }),
    );
    const sameLife = (id: number, snapshot: DuelParticipantSnapshot) =>
      this.world.getComponent(id, COMPONENT.Alive) === snapshot.life &&
      snapshot.life.alive &&
      snapshot.version !== undefined &&
      aliveLifeVersion(snapshot.life) === snapshot.version &&
      this.world.getComponent(id, COMPONENT.Role) === snapshot.role &&
      snapshot.role?.role === snapshot.roleId &&
      snapshot.role?.camp === snapshot.camp;
    for (const pick of picks
      .filter((item): item is NonNullable<typeof item> => item !== null)
      .sort((a, b) => a.actorId - b.actorId)) {
      const valid = () =>
        isCurrent() &&
        sameLife(pick.actorId, pick.actor) &&
        getKnightState(pick.actor.role) === pick.state &&
        pick.state.canDuel &&
        pick.target !== undefined &&
        sameLife(pick.action.args.target_id, pick.target);
      if (
        !valid() ||
        !this.gateway.validateAndSanitize(this.world, pick.actorId, pick.action, {
          phase: Phase.Day,
          duelWindow: window,
          allowKnightDuel: true,
        }).ok ||
        !valid()
      )
        continue;
      if (!commit) throw new Error("knight_duel_commit_missing");
      const selection = { actorId: pick.actorId, targetId: pick.action.args.target_id },
        outcome = await commit(selection);
      if (outcome === "rejected") continue;
      return { selection, endsDay: outcome === "night" || outcome === "terminal" };
    }
    return empty;
  }
}

/**
 * Exposes the Knight's readonly native-state view to the daytime duel window.
 * Inputs are current role components before eligibility and commit rechecks;
 * outputs are the original stored reference, never a copied resource snapshot.
 * The window may read identity and availability; only the Knight commit consumes
 * stock. Replacement and terminal window failures remain the window owner's checks.
 */
export { getKnightState } from "./state";

/**
 * 负责白天自爆、骑士决斗和辩论窗口的有序装配及辩论重入政策。输入是调用方现场读取
 * World、角色注册、网关和事件的端口；输出为三个原窗口实例的窄视图与同步准入检查。
 * 构造顺序固定为自爆、决斗、辩论，首个读取／构造错误停止后续步骤，不回滚前缀。
 * 机制仍拥有许可、状态、付款与关闭；组合不缓存演员、改变配置、推进阶段或判断胜负。
 */
import type { GameEvent } from "@ai-werewolf-arena/game-contract";
import type { World } from "../core/domain/world";
import type { RoleRegistry } from "../core/domain/registries/role_registry";
import type { ToolGateway } from "../game/gateway/tool_gateway";
import type { DaytimeInterruptionComposition } from "../game/engine/daytime-interruption-contracts";
import { SelfDestructWindow } from "./self-destruct-window";
import { KnightDuelWindow } from "../game/engine/knight_duel_window";
import { DebaterWindow } from "../game/mechanisms/roles/debater/window";
import { hasActiveDebate } from "../game/mechanisms/roles/debater/authority";

/** 延迟读取保留每次原调用点；窗口捕获构造时引用，重入检查则读取执行时的 World。 */
export interface DaytimeInterruptionRuntime {
  world(): World;
  roleRegistry(): RoleRegistry;
  toolGateway(): ToolGateway;
  events(): GameEvent[];
}

export function createDaytimeInterruptionComposition(
  runtime: DaytimeInterruptionRuntime,
): DaytimeInterruptionComposition {
  // 每个 new 先查找原构造器，再依原顺序读取参数；不要先收齐一次 World／网关快照。
  const selfDestruct = new SelfDestructWindow(
    runtime.world(),
    runtime.roleRegistry(),
    runtime.toolGateway(),
  );
  const duel = new KnightDuelWindow(runtime.world(), runtime.toolGateway());
  const debate = new DebaterWindow(runtime.world(), runtime.toolGateway(), runtime.events());

  return {
    selfDestruct,
    duel,
    debate,
    assertEntry() {
      // 即使调用方已失效，仍先拒绝现场已开启辩论；没有新预约、撤销或已付效果回滚。
      if (hasActiveDebate(runtime.world())) throw new Error("debate_window_reentry");
    },
  };
}

/**
 * 单元测试验证白天组合的现场 getter 顺序、失败前缀和最早重入拒绝。输入为独立 World、
 * 手写读取轨迹与辩论 owner 的临时窗口；预期为字面顺序及原实例／错误引用，
 * 不复制窗口算法、生成 golden、运行整局或调用模型。
 */
import { expect, test } from "bun:test";
import { World } from "../../../src/core/domain/world";
import { RoleRegistry } from "../../../src/core/domain/registries/role_registry";
import type { GameEvent } from "../../../src/core/domain/model";
import { ToolGateway } from "../../../src/game/gateway/tool_gateway";
import { SelfDestructWindow } from "../../../src/rulesets/self-destruct-window";
import { KnightDuelWindow } from "../../../src/game/engine/knight_duel_window";
import { DayPipeline } from "../../../src/game/engine/phase_pipeline/day_pipeline";
import { DebaterWindow } from "../../../src/game/mechanisms/roles/debater/window";
import {
  closeDebate,
  openDebate,
  type DebateAuthority,
} from "../../../src/game/mechanisms/roles/debater/authority";
import { createDaytimeInterruptionComposition } from "../../../src/rulesets/daytime-interruption-composition";
import { sixPlayerMvpConfig } from "../../../src/runtime/scenarios/six_player_mvp";

test("constructs original windows in W/R/G, W/G, W/G/E order without snapshotting", () => {
  const trace: string[] = [],
    worlds = [new World(), new World(), new World()],
    gateways = [new ToolGateway(), new ToolGateway(), new ToolGateway()],
    registry = new RoleRegistry(),
    events: GameEvent[] = [];
  let worldsRead = 0,
    gatewaysRead = 0;
  const composition = createDaytimeInterruptionComposition({
    world: () => {
      trace.push(`world:${worldsRead + 1}`);
      return worlds[worldsRead++]!;
    },
    roleRegistry: () => (trace.push("registry"), registry),
    toolGateway: () => {
      trace.push(`gateway:${gatewaysRead + 1}`);
      return gateways[gatewaysRead++]!;
    },
    events: () => (trace.push("events"), events),
  });
  expect(trace).toEqual([
    "world:1",
    "registry",
    "gateway:1",
    "world:2",
    "gateway:2",
    "world:3",
    "gateway:3",
    "events",
  ]);
  expect(composition.selfDestruct).toBeInstanceOf(SelfDestructWindow);
  expect(composition.duel).toBeInstanceOf(KnightDuelWindow);
  expect(composition.debate).toBeInstanceOf(DebaterWindow);
  // 只在测试中核对原实例捕获引用；生产消费者仍只能使用窄执行端口。
  const self = composition.selfDestruct as unknown as {
      world: World;
      roleRegistry: RoleRegistry;
      toolGateway: ToolGateway;
    },
    duel = composition.duel as unknown as { world: World; gateway: ToolGateway },
    debate = composition.debate as unknown as {
      world: World;
      gateway: ToolGateway;
      events: GameEvent[];
    };
  expect(self.world).toBe(worlds[0]);
  expect(self.roleRegistry).toBe(registry);
  expect(self.toolGateway).toBe(gateways[0]);
  expect(duel.world).toBe(worlds[1]);
  expect(duel.gateway).toBe(gateways[1]);
  expect(debate.world).toBe(worlds[2]);
  expect(debate.gateway).toBe(gateways[2]);
  expect(debate.events).toBe(events);
});

test("second window gateway failure stops before Debater reads and preserves original error", () => {
  const trace: string[] = [],
    failure = new Error("controlled_second_gateway_failure"),
    world = new World(),
    gateway = new ToolGateway();
  let reads = 0;
  expect(() =>
    createDaytimeInterruptionComposition({
      world: () => (trace.push("world"), world),
      roleRegistry: () => (trace.push("registry"), new RoleRegistry()),
      toolGateway: () => {
        trace.push("gateway");
        if (++reads === 2) throw failure;
        return gateway;
      },
      events: () => (trace.push("events"), []),
    }),
  ).toThrow(failure);
  expect(trace).toEqual(["world", "registry", "gateway", "world", "gateway"]);
});

test("entry reads the late World while original windows retain their construction World", () => {
  const original = new World(),
    replacement = new World(),
    authority: DebateAuthority = {
      id: "controlled-debate",
      day: 1,
      actorId: 1,
      targetId: 2,
      stage: "challenge",
      participants: new Map(),
    },
    trace: string[] = [];
  let currentWorld = original;
  const composition = createDaytimeInterruptionComposition({
    world: () => (trace.push("world"), currentWorld),
    roleRegistry: () => new RoleRegistry(),
    toolGateway: () => new ToolGateway(),
    events: () => [],
  });
  trace.length = 0;
  currentWorld = replacement;
  openDebate(replacement, authority);
  try {
    expect(() => composition.assertEntry()).toThrow("debate_window_reentry");
    expect(trace).toEqual(["world"]);
    const debate = composition.debate as unknown as { world: World };
    expect(debate.world).toBe(original);
  } finally {
    closeDebate(replacement, authority);
  }
  expect(() => composition.assertEntry()).not.toThrow();
  expect(trace).toEqual(["world", "world"]);
});

test("pipeline rejects reentry before reading day or currentness and before provider work", async () => {
  const world = new World(),
    events: GameEvent[] = [],
    trace: string[] = [],
    pipeline = new DayPipeline({
      world,
      events,
      roleRegistry: new RoleRegistry(),
      toolGateway: new ToolGateway(),
    }),
    authority: DebateAuthority = {
      id: "controlled-pipeline-debate",
      day: 1,
      actorId: 1,
      targetId: 2,
      stage: "speech",
      participants: new Map(),
    };
  openDebate(world, authority);
  try {
    await expect(
      pipeline.execute(
        sixPlayerMvpConfig,
        { getAction: async () => (trace.push("provider"), null) },
        {
          get day(): number {
            trace.push("day");
            throw new Error("day_read_too_early");
          },
          get isCurrent(): () => boolean {
            trace.push("isCurrent");
            throw new Error("current_read_too_early");
          },
        },
      ),
    ).rejects.toThrow("debate_window_reentry");
    expect(trace).toEqual([]);
    expect(events).toEqual([]);
  } finally {
    closeDebate(world, authority);
  }
});

/**
 * 单元测试验证骑士真实阵营决斗、只读接收及有界 provider／actor／target 权限。输入保留原 locale、字面规则／目标修改及受控直接决斗收集／提交；精确库存、无身份泄露、错误身份和陈旧选择拒绝是预期，不推进完整 PhaseManager 周期或记录文件。
 */
import { expect, test } from "bun:test";
import { bootstrapGame } from "../../../../src/app/bootstrap";
import {
  Role,
  Camp,
  Phase,
  KnightDuelWindow,
  WinCondition,
  COMPONENT,
  DeathCause,
  type RoleComponent,
  type GameEvent,
  type ActionRequest,
} from "../../../../src/core";
import { sixPlayerMvpConfig } from "../../../../src/runtime/scenarios/six_player_mvp";
import { getKnightState, setKnightState } from "../../../../src/game/mechanisms/roles/knight/state";
import { commitKnightDuel } from "../../../../src/game/mechanisms/roles/knight/commit";
import { KnightDuelWindow as DuelCollector } from "../../../../src/game/engine/knight_duel_window";
import { GameActionRequestFactory } from "../../../../src/game/engine/action_request_factory";
import { ToolGateway } from "../../../../src/game/gateway/tool_gateway";
import { ActionReception } from "../../../../src/game/gateway/action-reception";
import { RoleCatalog } from "../../../../src/game/mechanisms/roles/catalog";
import {
  getDefaultRoleCatalog,
  getDefaultRoleContributions,
  createRoleCatalog,
} from "../../../../src/game/mechanisms/roles/role-catalog-assembly";
import { resolveInspection } from "../../../../src/game/mechanisms/roles/inspection";
import { setIdiotState } from "../../../../src/game/mechanisms/roles/idiot/ports";
import { DefaultTargetHintRegistry } from "../../../../src/game/mechanisms/llm/target_hint_registry";

const deck = [Role.Knight, Role.Wolf, Role.WolfKing, Role.Hunter, Role.Villager, Role.Villager];

const board = (window: KnightDuelWindow) => ({
  ...sixPlayerMvpConfig,
  winConditions: [WinCondition.SlaughterSide],
  roleSetups: [
    { role: Role.Knight, count: 1 },
    { role: Role.Wolf, count: 1 },
    { role: Role.WolfKing, count: 1 },
    { role: Role.Hunter, count: 1 },
    { role: Role.Villager, count: 2 },
  ],
  knight: { enabledWindows: [window] },
});

const role = (world: ReturnType<typeof bootstrapGame>["world"], id: number) =>
  world.getComponent(id, COMPONENT.Role)!;

const duel = (target_id: number) => ({ name: "duel" as const, args: { target_id, confirm: true } });

const req: ActionRequest = {
  actorId: 1,
  phase: Phase.Day,
  allowedTools: ["duel"],
  context: {
    day: 1,
    stage: KnightDuelWindow.AfterSpeeches,
    duel_window: KnightDuelWindow.AfterSpeeches,
    visible_events: [],
    turn_constraints: {},
  },
};

for (const locale of ["zh-CN", "en"] as const)
  test(`${locale}: inspection disguise and revealed Idiot immunity neither alter true-camp duels nor leak through target hints`, () => {
    const { world } = bootstrapGame(
      {
        ...board(KnightDuelWindow.AfterSpeeches),
        roleSetups: [
          { role: Role.Knight, count: 1 },
          { role: Role.Wolf, count: 1 },
          { role: Role.Seer, count: 1 },
          { role: Role.Idiot, count: 1 },
          { role: Role.Villager, count: 2 },
        ],
      },
      {
        locale,
        fixedRoles: [Role.Knight, Role.Wolf, Role.Seer, Role.Idiot, Role.Villager, Role.Villager],
      },
    );
    const defaultCatalog = getDefaultRoleCatalog(),
      catalog = createRoleCatalog({
        contributions: getDefaultRoleContributions().map((profile) =>
          profile.metadata.role === Role.Wolf
            ? { ...profile, runtime: { ...profile.runtime, inspectionLabels: { camp: Camp.Good } } }
            : profile,
        ),
      });
    expect(resolveInspection(world, 2, "camp", catalog)).toEqual({ kind: "camp", camp: Camp.Good });
    setIdiotState(role(world, 4), { revealed: true });
    expect(catalog.participation(role(world, 4)).canBeExiled).toBe(false);
    const hint = new DefaultTargetHintRegistry().buildActionableIdsHint({
      actorId: 1,
      actorRole: Role.Knight,
      allowedTools: ["duel"],
      world,
      roleCatalog: catalog,
    });
    expect(hint).toContain("2, 3, 4, 5, 6");
    expect(new ActionReception(world).validate(req, "duel", duel(4).args).ok).toBe(true);
    const events: GameEvent[] = [];
    expect(commitKnightDuel(world, { actorId: 1, targetId: 2 }, Phase.Day, events)).toEqual({
      deaths: [2],
      sources: { 2: [DeathCause.Duel] },
      endsDay: true,
    });
    expect(events[0].payload).toEqual({ actorId: 1, targetId: 2, result: "wolf" });
    const other = bootstrapGame(
      {
        ...board(KnightDuelWindow.AfterSpeeches),
        roleSetups: [
          { role: Role.Knight, count: 1 },
          { role: Role.Wolf, count: 1 },
          { role: Role.Seer, count: 1 },
          { role: Role.Idiot, count: 1 },
          { role: Role.Villager, count: 2 },
        ],
      },
      {
        locale,
        fixedRoles: [Role.Knight, Role.Wolf, Role.Seer, Role.Idiot, Role.Villager, Role.Villager],
      },
    );
    setIdiotState(role(other.world, 4), { revealed: true });
    expect(commitKnightDuel(other.world, { actorId: 1, targetId: 4 }, Phase.Day, [])).toEqual({
      deaths: [1],
      sources: { 1: [DeathCause.DuelFailure] },
      endsDay: false,
    });
  });

test("an optional duel provider failure propagates unchanged and consumes no resource or public fact", async () => {
  const config = board(KnightDuelWindow.AfterSpeeches),
    { world } = bootstrapGame(config, { fixedRoles: deck }),
    events: GameEvent[] = [],
    fault = new Error("original_duel_failure");
  let commits = 0;
  await expect(
    new DuelCollector(world, new ToolGateway()).execute(
      config,
      new GameActionRequestFactory(world, events, 1),
      {
        async getAction() {
          throw fault;
        },
      },
      KnightDuelWindow.AfterSpeeches,
      () => true,
      async () => {
        commits++;
        return "night";
      },
    ),
  ).rejects.toBe(fault);
  expect(commits).toBe(0);
  expect(getKnightState(role(world, 1))?.canDuel).toBe(true);
  expect(events).toEqual([]);
});

for (const locale of ["zh-CN", "en"] as const)
  test(`${locale}: strict readonly duel receipt and true-camp commit hide non-wolf third-party identity`, () => {
    const { world } = bootstrapGame(board(KnightDuelWindow.AfterSpeeches), {
        locale,
        fixedRoles: deck,
      }),
      receive = new ActionReception(world);
    expect(receive.validate(req, "duel", duel(2).args).ok).toBe(true);
    for (const target of [1, 999, 3.5])
      expect(receive.validate(req, "duel", duel(target).args)).toMatchObject({
        ok: false,
        error: "knight_duel_target",
      });
    expect(receive.validate(req, "duel", { target_id: 2, confirm: "true" }).ok).toBe(false);
    expect(receive.validate(req, "duel", { target_id: null, confirm: true }).ok).toBe(false);
    expect(receive.validate({ ...req, phase: Phase.Night }, "duel", duel(2).args)).toMatchObject({
      ok: false,
      error: "knight_duel_window",
    });
    expect(
      receive.validate(
        { ...req, context: { ...req.context, duel_window: undefined } },
        "duel",
        duel(2).args,
      ).ok,
    ).toBe(false);
    expect(
      receive.validate(
        { ...req, context: { ...req.context, stage: "day_speech" } },
        "duel",
        duel(2).args,
      ).ok,
    ).toBe(false);
    expect(receive.validate({ ...req, actorId: 4 }, "duel", duel(2).args).ok).toBe(false);
    expect(getKnightState(role(world, 1))).toEqual({ canDuel: true });
    role(world, 4).camp = Camp.ThirdParty;
    const events: GameEvent[] = [];
    expect(commitKnightDuel(world, { actorId: 1, targetId: 4 }, Phase.Day, events)).toEqual({
      deaths: [1],
      sources: { 1: [DeathCause.DuelFailure] },
      endsDay: false,
    });
    expect(events).toEqual([
      {
        timestamp: expect.any(Number),
        type: "knight_duel",
        payload: { actorId: 1, targetId: 4, result: "not_wolf" },
      },
    ]);
    expect(JSON.stringify(events)).not.toContain("third_party");
    expect(getKnightState(role(world, 1))).toEqual({ canDuel: false });
    expect(world.getAliveEntityIds()).toHaveLength(6);
    expect(commitKnightDuel(world, { actorId: 1, targetId: 2 }, Phase.Day, events)).toBeNull();
  });

for (const locale of ["zh-CN", "en"] as const)
  test(`${locale}: multiple Knights use the smallest eligible actor and discard role/resource/target-life changes without spending others`, async () => {
    const fixed = [Role.Knight, Role.Knight, Role.Wolf, Role.Seer, Role.Villager, Role.Villager],
      config = {
        ...board(KnightDuelWindow.AfterSpeeches),
        roleSetups: [
          { role: Role.Knight, count: 2 },
          { role: Role.Wolf, count: 1 },
          { role: Role.Seer, count: 1 },
          { role: Role.Villager, count: 2 },
        ],
      };
    for (const mode of ["normal", "resource", "target", "role", "phase"] as const) {
      const { world } = bootstrapGame(config, { locale, fixedRoles: fixed }),
        events: GameEvent[] = [],
        original = getKnightState(role(world, 1))!;
      let current = true,
        commits = 0;
      const result = await new DuelCollector(world, new ToolGateway()).execute(
        config,
        new GameActionRequestFactory(world, events, 1),
        {
          async getAction(request) {
            if (request.actorId === 2) {
              if (mode === "resource") setKnightState(role(world, 1), { canDuel: true });
              if (mode === "target") {
                const life = world.getComponent(3, COMPONENT.Alive)!;
                life.alive = false;
                life.alive = true;
              }
              if (mode === "role") role(world, 1).role = Role.Villager;
              if (mode === "phase") current = false;
            }
            return duel(3);
          },
        },
        KnightDuelWindow.AfterSpeeches,
        () => current,
        async (choice) => {
          commits++;
          expect(commitKnightDuel(world, choice, Phase.Day, events)).not.toBeNull();
          return "night";
        },
      );
      expect(commits).toBe(mode === "target" || mode === "phase" ? 0 : 1);
      expect(result.selection?.actorId ?? null).toBe(
        mode === "target" || mode === "phase" ? null : mode === "normal" ? 1 : 2,
      );
      expect(original.canDuel).toBe(mode !== "normal");
      if (mode === "normal") expect(getKnightState(role(world, 2))?.canDuel).toBe(true);
    }
  });

/**
 * 单元测试验证注册配置往返至有界角色、Gateway、骑士窗口和双语提示消费者。输入为原女巫规则／窗口矩阵、固定角色与受控空回复；手写自救／窗口／提示／未知字段是预期，不执行完整阶段、录制文件或传输，不替换 golden。
 */
import { expect, spyOn, test } from "bun:test";
import { RULESET } from "@ai-werewolf-arena/game-catalog";
import { text, term } from "@ai-werewolf-arena/game-text";
import { bootstrapGame } from "../../../src/app/bootstrap";
import {
  COMPONENT,
  KnightDuelWindow,
  Phase,
  PotionType,
  Role,
  StatusMark,
  WitchSelfHealRule,
  type BoardConfig,
  type GameEvent,
} from "../../../src/core";
import type { RoleComponent } from "../../../src/core/domain/components/role";
import type { StatusMarksComponent } from "../../../src/core/domain/components/status_marks";
import { boardConfigSchema } from "../../../src/core/domain/board_schema";
import { GameActionRequestFactory } from "../../../src/game/engine/action_request_factory";
import { KnightDuelWindow as DuelExecutor } from "../../../src/game/engine/knight_duel_window";
import { ToolGateway } from "../../../src/game/gateway/tool_gateway";
import { getDefaultConfigRenderRegistry } from "../../../src/game/mechanisms/prompt/config_render_registry";
import { getDefaultRoleCatalog } from "../../../src/game/mechanisms/roles/role-catalog-assembly";
import { getWitchState } from "../../../src/game/mechanisms/roles/witch/ports";
import {
  boardDefinitionFromConfig,
  parseBoardDefinition,
} from "../../../src/runtime/config/board_definition";

const roleIds = [Role.Wolf, Role.Witch, Role.Knight, Role.Villager, Role.Villager, Role.Villager];

const base: BoardConfig = {
  ...sixPlayerBase(),
  roleSetups: [...new Set(roleIds)].map((role) => ({
    role,
    count: roleIds.filter((id) => id === role).length,
  })),
};

function sixPlayerBase(): BoardConfig {
  return {
    boardSize: 6,
    enableSheriff: false,
    hooks: { onDaybreak: false, onPreElection: false, onPreVote: false, onPerSpeechGap: false },
    roleSetups: [],
  };
}

for (const rule of Object.values(WitchSelfHealRule))
  for (const windows of [
    [],
    ...Object.values(KnightDuelWindow).map((window) => [window]),
    Object.values(KnightDuelWindow),
  ]) {
    test(`${rule}/${windows.join("+")}: registered parameters survive public defaults, runtime consumption and both prompt locales`, async () => {
      const initial: BoardConfig = {
        ...base,
        witch: { canSelfHeal: rule },
        knight: { enabledWindows: windows },
      };
      const definition = boardDefinitionFromConfig("closure_test", initial);
      expect(definition.ruleset).toEqual(RULESET);
      expect(definition.roles.witch).toEqual({
        selfHeal: rule,
        knifeVisibility: "awa_with_heal_v1",
        potionPolicy: "awa_one_native_v1",
      });
      expect(definition.roles.knight).toEqual({ enabledWindows: windows });
      const resolved = parseBoardDefinition(definition);
      expect(boardDefinitionFromConfig(definition.id, resolved.config)).toEqual(definition);
      expect(boardConfigSchema.parse(resolved.config)).toEqual(resolved.config);
      const omitted = structuredClone(definition);
      if (rule === WitchSelfHealRule.Disabled) omitted.roles.witch = {};
      if (windows.length === 1 && windows[0] === KnightDuelWindow.AfterSpeeches)
        omitted.roles.knight = {};
      expect(parseBoardDefinition(omitted).config).toEqual(resolved.config);
      const game = bootstrapGame(resolved.config, { fixedRoles: roleIds });
      const gateway = new ToolGateway();
      const witch = game.world.getComponent(2, COMPONENT.Role)!;
      expect(getWitchState(witch)?.selfHealRule).toBe(rule);
      game.world
        .getComponent(2, COMPONENT.StatusMarks)!
        .add(StatusMark.WolfKillMark);
      for (const day of [1, 2]) {
        expect(
          gateway.validateAndSanitize(
            game.world,
            2,
            { name: "use_potion", args: { target_id: 2, potion_type: PotionType.Heal } },
            { phase: Phase.Night, day },
          ).ok,
        ).toBe(
          rule === WitchSelfHealRule.Always ||
            (rule === WitchSelfHealRule.FirstNightOnly && day === 1),
        );
      }
      const events: GameEvent[] = [],
        requested: KnightDuelWindow[] = [];
      const requests = new GameActionRequestFactory(game.world, events, 1);
      for (const window of Object.values(KnightDuelWindow))
        await new DuelExecutor(game.world, gateway).execute(
          resolved.config,
          requests,
          {
            async getAction(request) {
              requested.push(request.context.duel_window!);
              return null;
            },
          },
          window,
          () => true,
        );
      expect(requested).toEqual(
        Object.values(KnightDuelWindow).filter((window) => windows.includes(window)),
      );
      for (const locale of ["zh-CN", "en"] as const) {
        const rendered = getDefaultConfigRenderRegistry().renderBoardConfigPrompt(
          resolved.config,
          locale,
        );
        const key =
          rule === WitchSelfHealRule.Always
            ? "prompt.config.self_heal_always"
            : rule === WitchSelfHealRule.FirstNightOnly
              ? "prompt.config.self_heal_first"
              : "prompt.config.self_heal_disabled";
        expect(rendered).toContain(text(locale, key));
        expect(rendered).toContain(
          text(locale, "prompt.config.knight_windows", {
            windows:
              windows.map((window) => term("stage", window, locale)).join(", ") ||
              text(locale, "common.disabled"),
          }),
        );
      }
    });
  }

test("reverse writing calls the contributor and rejects internal fields which have no consumer", () => {
  const contribution = getDefaultRoleCatalog().requireRuntime(Role.Witch).configuration!;
  const serialize = spyOn(contribution, "serialize");
  try {
    boardDefinitionFromConfig("closure_test", base);
    expect(serialize).toHaveBeenCalledTimes(1);
  } finally {
    serialize.mockRestore();
  }
  const extra = { ...base, witch: { canSelfHeal: WitchSelfHealRule.Always, selfHela: true } };
  expect(() => boardDefinitionFromConfig("closure_test", extra)).toThrow("config.witch.selfHela");
  const unknown = { ...base, unusedRule: true };
  expect(() => boardDefinitionFromConfig("closure_test", unknown)).toThrow("config.unusedRule");
});
